# Downloads the four public datasets of App. M.2 (about 4.6 GB) into extensions/structural_audit/data/.
# The BabyAI levels are generated by gen_babyai.py instead.
import os
from huggingface_hub import snapshot_download
D = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data")
SOURCES = [  # (dataset, local folder, files)
    ("agent-eto/eto-sft-trajectory", "eto", ["README.md", "data/*_sft.json"]),  # data/eto/data/*_sft.json
    ("nebius/SWE-agent-trajectories", "swe_agent", ["README.md", "data/train-*.parquet"]),  # data/swe_agent/data/
    ("nebius/SWE-rebench-openhands-trajectories", "openhands", ["README.md", "LICENSE", "trajectories.parquet"]),
    ("Embodied-CoT/embodied_features_bridge", "ecot", ["README.md", "embodied_features_bridge.json"]),
]
for repo, sub, patterns in SOURCES:
    p = snapshot_download(repo, repo_type="dataset", local_dir=os.path.join(D, sub), allow_patterns=patterns)
    print(repo, "->", p, flush=True)
